export type FlashcardReportReason =
  | 'incorrect-knowledge'
  | 'incorrect-answer'
  | 'unclear-question'
  | 'inappropriate-content'
  | 'other'

export type ReportableFlashcard = {
  flashcardId: string
  deckId: string
  front: string
  back: string
}

/** Client request. User identity is intentionally supplied by server authentication. */
export type SubmitFlashcardReportRequest = {
  flashcardId: string
  deckId: string
  reason: FlashcardReportReason
  description: string
  suggestedCorrection: string
}

/** Mock/API response; these metadata fields are not generated by the client form. */
export type FlashcardReport = SubmitFlashcardReportRequest & {
  reportId: string
  status: 'PENDING'
  createdAt: string
}

export type FlashcardReportSubmitter = (
  request: SubmitFlashcardReportRequest,
) => Promise<FlashcardReport>

export type FlashcardReportFormValues = {
  reason: FlashcardReportReason | ''
  description: string
  suggestedCorrection: string
}

export type FlashcardReportFormErrors = Partial<
  Record<'reason' | 'description' | 'suggestedCorrection', string>
>
